public static int countWays(int n) {
    if (n <= 2) {
        return n;
    }
    return countWays(n - 1) + countWays(n - 2);
}

public static int countPaths(int r, int c) {
    if (r == 0 || c == 0) {
        return 1;
    }
    return countPaths(r - 1, c) + countPaths(r, c - 1);
}

